import{_ as i,o as a,c as r,j as e}from"./chunks/framework.44aEvdQQ.js";const m=JSON.parse(`{"title":"Retainers Without Timely Data Are Just Guesses","description":"A retainer is a commitment to deliver a volume of work within a period. If you don't know where you are until the invoice, you've already lost.","frontmatter":{"title":"Retainers Without Timely Data Are Just Guesses","date":"2026-02-19","series":"Business Logic","description":"A retainer is a commitment to deliver a volume of work within a period. If you don't know where you are until the invoice, you've already lost.","sidebar":false,"prev":false,"next":false},"headers":[],"relativePath":"blog/07-retainers-are-weird.md","filePath":"blog/07-retainers-are-weird.md","blogPosts":[{"url":"/blog/21-not-everyone-works-forty-hours","fm":{"title":"Not Everyone Works Forty Hours","date":"2026-03-29","series":"Features","description":"Capacity planning only works if the system knows how each person actually works. VERA was treating your contractors like full-time employees. It no longer does."}},{"url":"/blog/20-when-done-means-done","fm":{"title":"When Done Means Done","date":"2026-03-25","series":"AI Behaviour","description":"A confirmation that nothing happened behind it is worse than no confirmation at all. We fixed the moment where trust breaks."}},{"url":"/blog/19-the-briefing","fm":{"title":"The Briefing That Replaced the Monday Check-in","date":"2026-03-24","series":"Features","description":"The morning summary now answers two questions simultaneously: what am I supposed to be working on, and where do my projects stand?"}},{"url":"/blog/18-sheets-formulas-as-code","fm":{"title":"Building the Dashboard the Owner Actually Needs","date":"2026-03-15","series":"Data Model","description":"A live dashboard that answers the real questions: which projects are healthy, which are at risk, and what the business earned this month."}},{"url":"/blog/17-two-spreadsheets","fm":{"title":"The Dashboard Is Always Current","date":"2026-03-13","series":"Architecture","description":"The client''s reporting view and the database are separate spreadsheets. The client can never accidentally break the data — and they never have to request a report."}},{"url":"/blog/16-column-order-is-the-api","fm":{"title":"The Invisible Contract in the Spreadsheet","date":"2026-03-12","series":"Data Model","description":"Google Sheets doesn''t enforce its own structure. We had to. The rules we built to keep the data trustworthy."}},{"url":"/blog/14-agile-as-billing-model","fm":{"title":"Agile as a Billing Model","date":"2026-03-08","series":"Business Logic","description":"A sprint is a delivery unit and a revenue recognition unit. Timeliness of logging determines timeliness of revenue — they''re the same thing."}},{"url":"/blog/15-ooo-is-a-financial-event","fm":{"title":"Absence Is Data Too","date":"2026-03-08","series":"Business Logic","description":"Time off is a cost. If it doesn''t appear in the same system as time worked, the capacity picture is wrong and the P&L is incomplete."}},{"url":"/blog/13-design-md-rethink","fm":{"title":"Writing It Down Made Us Confront What We''d Built","date":"2026-03-07","series":"Architecture","description":"Six weeks in, we stopped and wrote down every decision we''d made. Several of them turned out to be wrong."}},{"url":"/blog/12-phased-expansion","fm":{"title":"What Becomes Possible When the Data Is Real","date":"2026-03-03","series":"Features","description":"Once time tracking is accurate and timely, a layer of project intelligence that was previously impossible becomes straightforward."}},{"url":"/blog/11-multi-tenancy-bugs","fm":{"title":"Reliability Is the Promise","date":"2026-03-01","series":"Architecture","description":"Timeliness only works if the system is there when the moment arrives. Getting multi-tenant reliability right was non-negotiable."}},{"url":"/blog/10-multi-tenancy","fm":{"title":"Each Client Gets Their Own VERA","date":"2026-02-25","series":"Architecture","description":"Multi-tenancy wasn''t a feature request. It was the point. A tool that feels shared feels like someone else''s."}},{"url":"/blog/09-timebot-becomes-vera","fm":{"title":"TimeBot Becomes VERA","date":"2026-02-22","series":"Origins","description":"A name signals a relationship. We weren''t building a utility."}},{"url":"/blog/07-retainers-are-weird","fm":{"title":"Retainers Without Timely Data Are Just Guesses","date":"2026-02-19","series":"Business Logic","description":"A retainer is a commitment to deliver a volume of work within a period. If you don''t know where you are until the invoice, you''ve already lost."}},{"url":"/blog/08-snapshots-version-control-spreadsheet","fm":{"title":"The Business Was There Last Tuesday Too","date":"2026-02-19","series":"Infrastructure","description":"When data is live and timely, the next question is whether you can go back. We built that in from the start."}},{"url":"/blog/06-roles-and-dollars","fm":{"title":"The Data Is Only Worth Protecting If It''s Worth Something","date":"2026-02-17","series":"Permissions","description":"When the data is timely and accurate, the financial numbers become real. Real numbers need to reach the right people — and not the wrong ones."}},{"url":"/blog/04-schema-grows-up","fm":{"title":"Making a Slack Message Do the Work of a Form","date":"2026-02-12","series":"Data Model","description":"We removed the interface. That meant every piece of information the owner needed had to be captured from a casual Slack message without making that message any harder to send."}},{"url":"/blog/05-prompt-engineering-wars","fm":{"title":"The Clarifying Questions Problem","date":"2026-02-12","series":"AI Behaviour","description":"Timeliness is the whole product. Any friction that risks the timing is a product failure."}},{"url":"/blog/03-socket-mode-railway","fm":{"title":"The Deployment That Didn''t Require a Web App","date":"2026-02-11","series":"Infrastructure","description":"We needed to deploy without adding anything to the client''s stack. Socket Mode and Railway made that possible for almost nothing."}},{"url":"/blog/01-the-problem","fm":{"title":"The Problem That Made VERA Necessary","date":"2026-02-10","series":"Origins","description":"Every time tracking tool ever built starts from the wrong assumption. We found the one thing that fixes it."}},{"url":"/blog/02-day-one-slack-claude-sheets","fm":{"title":"Day One: Slack → Claude → Google Sheets","date":"2026-02-10","series":"Origins","description":"The three components we chose on day one — and why each one was chosen specifically because it required no new interface."}}]}`),s={name:"blog/07-retainers-are-weird.md"};function o(n,t,l,h,d,u){return a(),r("div",null,[...t[0]||(t[0]=[e("p",null,"The retainer is the most common commercial arrangement in professional services, and the one most likely to go wrong quietly.",-1),e("p",null,"A fixed-price job goes wrong loudly — you hit the budget and you know it. A time and materials job is transparent by construction. But a retainer runs in the background. The hours accumulate. The month passes. And then the invoice moment arrives and everyone has a different number in their head.",-1),e("p",null,"The client thinks they've had good value because they've been responsive. The agency thinks they've been efficient because nobody complained. Then someone actually adds up the hours and finds they've delivered 140 hours against a 100-hour retainer, at a rate that doesn't cover the overage. That's not a billing conversation. That's a margin problem that's been building for three months.",-1),e("hr",null,null,-1),e("p",null,"The only way to manage a retainer properly is to know where you are in real time — not at invoice, not at month end, but now. This week.",-1),e("p",null,"When hours are logged at the moment they're worked, the retainer status is always current. VERA tracks burn rate against contracted hours and surfaces it every morning for the managers and owners who need to see it. If a project is at 80% of its hours with a week left in the month, that's visible before the overrun happens, not after.",-1),e("p",null,`We modelled retainers as a fundamentally different project type from fixed price or time and materials, because they are. A retainer isn't a budget — it's a rhythm. It resets each month. The health question isn't "are we over budget" but "are we on pace." That distinction changes what you measure and how you surface it.`,-1),e("p",null,"The insight that made it work was the same as everything else in VERA: the data has to be timely for the numbers to mean anything. A retainer dashboard built on Friday's backfilled entries is not a retainer dashboard. It's a retrospective.",-1)])])}const p=i(s,[["render",o]]);export{m as __pageData,p as default};
